'use strict';
const api='../api/index.php';const $=id=>document.getElementById(id);
let installPrompt=null;
function updateNetworkStatus(){const offline=!navigator.onLine;$('networkStatus').classList.toggle('hidden',!offline);document.querySelector('#bookingForm button[type="submit"],#bookingForm button:not([type])').disabled=offline}
window.addEventListener('online',()=>{updateNetworkStatus();loadSlots().catch(showError)});window.addEventListener('offline',updateNetworkStatus);updateNetworkStatus();
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('installApp').classList.remove('hidden')});
$('installApp').onclick=async()=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('installApp').classList.add('hidden')};
window.addEventListener('appinstalled',()=>{$('installApp').classList.add('hidden')});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}));
function bangkokDate(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
async function loadSlots(){const response=await fetch(`${api}?action=public-slots&date=${$('bookingDate').value}`,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error);$('onlineSlot').innerHTML=body.data.map(x=>`<option value="${x.id}">${x.start_time}–${x.end_time} น. · ${x.branch_name} · ${x.department_name}</option>`).join('')||'<option value="">ไม่มี Slot ที่เปิดรับ</option>'}
function showError(error){$('bookingError').textContent=error.message;$('bookingError').classList.remove('hidden')}
$('bookingDate').value=bangkokDate();$('bookingDate').min=bangkokDate();$('bookingDate').onchange=()=>loadSlots().catch(showError);loadSlots().catch(showError);
$('bookingForm').onsubmit=async event=>{event.preventDefault();$('bookingError').classList.add('hidden');if(!navigator.onLine){showError(new Error('กรุณาเชื่อมต่ออินเทอร์เน็ตก่อนยืนยันการจอง'));return}try{const response=await fetch(`${api}?action=create-booking`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({slot_id:+$('onlineSlot').value,customer_name:$('onlineName').value,customer_phone:$('onlinePhone').value,source:'ONLINE',idempotency_key:crypto.randomUUID()})});const body=await response.json();if(!response.ok)throw new Error(body.error||'จองคิวไม่สำเร็จ');render(body.booking)}catch(error){showError(error)}};
function render(booking){const url=new URL('status.html',location.href);url.searchParams.set('t',booking.public_id);const qr=qrcode(0,'M');qr.addData(url.href);qr.make();$('bookingQr').src=qr.createDataURL(7,10);$('bookingStatusLink').href=url.href;$('bookingReference').textContent=`เลขอ้างอิง ${booking.reference_no}`;$('bookingToken').textContent=booking.public_id;$('bookingPanel').classList.add('hidden');$('bookingResult').classList.remove('hidden')}
$('bookAgain').onclick=()=>{$('bookingResult').classList.add('hidden');$('bookingPanel').classList.remove('hidden')};$('saveBooking').onclick=()=>{const link=document.createElement('a');link.href=$('bookingQr').src;link.download='K-QOnline-QR.png';link.click()};
